  let changedAt = -Infinity, detailedFailures = 0, detailedRetryAt = -Infinity;
  let trialDuration = 0, trialCount = 0, trialSlow = 0, trialSlowTime = 0, trialLongest = 0;
  let recoveryFrames = 0, clusteredStalls = 0, stallStart = 0;
